#!/usr/bin/env python3
"""Generate IconsLucide.h from lucide-static info.json.

Run once after pulling a new lucide.ttf - outputs thirdparty/lucide/IconsLucide.h
with ICON_LC_* macros for the 40 glyphs Aura UI uses.
"""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
info = json.load(open(os.path.join(HERE, 'info.json'), encoding='utf-8'))

# macro_name -> lucide key (dashed name)
NEEDED = [
    ('PLUS', 'plus'),
    ('MINUS', 'minus'),
    ('X', 'x'),
    ('CHECK', 'check'),
    ('CHEVRON_DOWN', 'chevron-down'),
    ('CHEVRON_RIGHT', 'chevron-right'),
    ('ELLIPSIS_V', 'ellipsis-vertical'),
    ('SEARCH', 'search'),
    ('FILTER', 'filter'),
    ('SETTINGS', 'settings'),
    ('REFRESH', 'refresh-cw'),
    ('SAVE', 'save'),
    ('DOWNLOAD', 'download'),
    ('UPLOAD', 'upload'),
    ('COPY', 'copy'),
    ('FOLDER', 'folder'),
    ('FOLDER_OPEN', 'folder-open'),
    ('PLAY', 'play'),
    ('PAUSE', 'pause'),
    ('STOP', 'square'),
    ('SKIP_FORWARD', 'skip-forward'),
    ('SKIP_BACK', 'skip-back'),
    ('VOLUME_2', 'volume-2'),
    ('VOLUME_X', 'volume-x'),
    ('FILE', 'file'),
    ('FILE_AUDIO', 'file-audio'),
    ('FILE_MUSIC', 'file-music'),
    ('TRASH', 'trash-2'),
    ('PENCIL', 'pencil'),
    ('LOADER', 'loader'),
    ('INFO', 'info'),
    ('ALERT_TRIANGLE', 'triangle-alert'),
    ('ALERT_CIRCLE', 'circle-alert'),
    ('CHECK_CIRCLE', 'circle-check'),
    ('CIRCLE', 'circle'),
    ('ARROW_UP', 'arrow-up'),
    ('ARROW_DOWN', 'arrow-down'),
    ('ARROW_UP_DOWN', 'arrow-up-down'),
    ('PANEL_LEFT', 'panel-left'),
    ('PANEL_RIGHT', 'panel-right'),
    ('EYE', 'eye'),
    ('EYE_OFF', 'eye-off'),
    ('SEND', 'send'),
    ('EXTERNAL_LINK', 'external-link'),
    ('LINK', 'link-2'),
]

def utf8_escaped(cp):
    b1 = 0xE0 | (cp >> 12)
    b2 = 0x80 | ((cp >> 6) & 0x3F)
    b3 = 0x80 | (cp & 0x3F)
    return '"\\x{:02x}\\x{:02x}\\x{:02x}"'.format(b1, b2, b3)

# Resolve codepoints
rows = []
missing = []
codepoints = []
for macro, key in NEEDED:
    if key not in info:
        missing.append(key)
        continue
    ec = info[key]['encodedCode']   # e.g. "\e585"
    # encodedCode is literally the 5-char backslash-escape "\\eXXXX" in JSON
    # Python loads it as the 5-char string "\eXXXX" (backslash + e + 4 hex).
    if ec.startswith('\\e') and len(ec) >= 6:
        cp = int(ec[2:], 16)
    else:
        # fallback: parse unicode field "&#NNNNN;"
        uni = info[key].get('unicode', '').replace('&#', '').replace(';', '')
        cp = int(uni)
    rows.append((macro, key, cp))
    codepoints.append(cp)

if missing:
    print('Missing keys:', missing)

cp_min = min(codepoints)
cp_max = max(codepoints)

header_lines = [
    '// thirdparty/lucide/IconsLucide.h',
    '// Auto-generated by thirdparty/lucide/_gen_header.py from lucide-static info.json.',
    '// Subset of 40 glyphs used by aura::ui. Regenerate after bumping lucide.ttf.',
    '#pragma once',
    '',
    '#define ICON_MIN_LC 0x{:04X}'.format(cp_min),
    '#define ICON_MAX_LC 0x{:04X}'.format(cp_max),
    '',
]
for macro, key, cp in rows:
    header_lines.append(
        '#define ICON_LC_{:16s} {}   // {} U+{:04X}'.format(
            macro, utf8_escaped(cp), key, cp))

out_path = os.path.join(HERE, 'IconsLucide.h')
with open(out_path, 'w', encoding='utf-8', newline='\n') as f:
    f.write('\n'.join(header_lines))
    f.write('\n')

print('Wrote', out_path)
print('Range: U+{:04X} - U+{:04X}'.format(cp_min, cp_max))
print('Glyphs:', len(rows))
